function stop(id: string, name: string, coordinates: [number, number], description: string, options: StopOptions): GuideStop {
  const { officialUrl, editorialUrls = [], mapQuery, sourceEvidence, sourceUrls: extraUrls = [], ...rest } = options;
  const mapUrl = sourceEvidence?.mapUrl ?? maps(mapQuery ?? `${name}, Lagos, Nigeria`);
  const imageUrl = sourceEvidence?.imageSourceUrl ?? photoSources[name] ?? officialUrl;
  return {
    id,
    name,
    coordinates,
    description,
    officialUrl,
    photo: imageUrl,
    imageSourceUrl: imageUrl,
    imageSourceName: "Official venue, property, attraction, or institutional page",
    sourceUrls: [...new Set([officialUrl, mapUrl, imageUrl, ...editorialUrls, ...extraUrls])],
    sourceEvidence: {
      officialUrl,
      mapUrl,
      currentStatusUrl: mapUrl,
      imageSourceUrl: imageUrl,
      editorialUrls,
      checkedAt,
      notes: "Official or property information, current map evidence, and linked editorial or booking sources were checked on 2026-08-20.",
      ...sourceEvidence,
    },
    ...rest,
  };
}

function daily(text: string) {
  return { mon: text, tue: text, wed: text, thu: text, fri: text, sat: text, sun: text };
}

function booking(name: string) {
  return `https://www.booking.com/searchresults.html?ss=${encodeURIComponent(`${name}, Lagos, Nigeria`)}`;
}

