function sourcesFor(stops: GuideStop[], categorySources: ListSource[]): ListSource[] {
  return [...new Map([
    ...categorySources,
    ...stops.flatMap((item) => [
      source(`${item.name} official or current page`, item.officialUrl ?? maps(item.name)),
      source(`${item.name} current map listing`, item.sourceEvidence?.mapUrl ?? maps(item.name)),
    ]),
  ].map((item) => [item.url, item] as const)).values()];
}

function guide(category: ListCategory, id: string, slug: string, seoSlug: string, title: string, description: string, stops: GuideStop[], guideSources: ListSource[], seoTitle: string, seoDescription: string): MapList {
  return {
    id,
    slug,
    seoSlug,
    seoTitle,
    seoDescription,
    title,
    description,
    url: maps(`${title} Lagos Nigeria`),
    category,
    location,
    creator: { id: `user-rguide-${category.toLowerCase()}`, name: `R ${category}`, avatar: avatar(category) },
    upvotes: 0,
    createdAt,
    stops,
    sources: guideSources,
  };
}

